//! Tests for the committed Round 12 example goldens.
//!
//! The golden standings readings of the standing example meet
//! and of the constructed meet are regenerated by the standings
//! command itself, and these pins fail if an example, a golden,
//! or the reading drifts away from the hand computed standings
//! of either meet, and the reconciliation pins read the report
//! and the table readings over the same files and fail when the
//! standings reading disagrees with them over the closings and
//! the close. The constructed meet carries the late entry shape
//! the standing meet cannot state, a competitor whose first
//! projecting read stands on the second day, and a pin states
//! that shape over the golden itself.

use std::fs;
use std::path::PathBuf;

use paceghost::cli::dispatch;
use paceghost::meet::{load_meet_file, meet_report, meet_standings, meet_table};
use paceghost::pytext::PText;

fn reader(bytes: &[u8]) -> Option<String> {
    let path = String::from_utf8_lossy(bytes).into_owned();
    let data = std::fs::read(path).ok()?;
    String::from_utf8(data).ok()
}

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

fn golden_lines(name: &str) -> Vec<String> {
    let golden = fs::read_to_string(examples_dir().join(name)).expect("the golden file reads");
    assert!(golden.ends_with('\n'));
    golden.lines().map(str::to_string).collect()
}

fn command_lines(command: &str, file: &str) -> Vec<String> {
    let argv: Vec<PText> = vec![
        PText::from_text(command),
        PText::from_text(examples_dir().join(file).to_str().unwrap()),
    ];
    let outcome = dispatch(&argv, &reader);
    assert_eq!(outcome.code, 0);
    outcome.stdout
}

fn load_example(file: &str) -> paceghost::meet::Meet {
    let (meet, defects) = load_meet_file(&examples_dir().join(file));
    assert_eq!(defects, Vec::<String>::new());
    meet.expect("the example meet loads")
}

#[test]
fn test_the_example_standings_match_the_golden_bytes() {
    let meet = load_example("meet.json");
    let lines = meet_standings(&meet).expect("the example standings read");
    assert_eq!(lines, golden_lines("meet-standings-golden.txt"));
}

#[test]
fn test_the_standings_command_prints_the_golden_standings() {
    assert_eq!(
        command_lines("standings", "meet.json"),
        golden_lines("meet-standings-golden.txt")
    );
}

#[test]
fn test_the_constructed_standings_match_the_golden_bytes() {
    let meet = load_example("constructed-meet-standings.json");
    let lines = meet_standings(&meet).expect("the constructed standings read");
    assert_eq!(lines, golden_lines("constructed-meet-standings-golden.txt"));
}

#[test]
fn test_the_standings_command_prints_the_constructed_golden() {
    assert_eq!(
        command_lines("standings", "constructed-meet-standings.json"),
        golden_lines("constructed-meet-standings-golden.txt")
    );
}

#[test]
fn test_the_golden_closings_are_the_report_closings_of_the_example() {
    let meet = load_example("meet.json");
    let report = meet_report(&meet).expect("the report reads");
    let golden = golden_lines("meet-standings-golden.txt");
    let report_closes: Vec<&String> = report
        .iter()
        .filter(|line| line.starts_with("close of the "))
        .collect();
    let golden_closes: Vec<&String> = golden
        .iter()
        .filter(|line| line.starts_with("close of the "))
        .collect();
    assert_eq!(golden_closes, report_closes);
}

#[test]
fn test_the_golden_close_states_the_table_close_of_the_example() {
    let meet = load_example("meet.json");
    let table = meet_table(&meet).expect("the table reads");
    let golden = golden_lines("meet-standings-golden.txt");
    let operator = table
        .iter()
        .find(|line| line.starts_with("competitor operator,"))
        .expect("the table names the operator");
    assert!(operator.ends_with("standing projection 750 at the close"));
    assert!(golden
        .iter()
        .any(|line| line == "competitor operator, standing projection 750 at the close"));
    let quiet = table
        .iter()
        .find(|line| line.starts_with("competitor quiet fork,"))
        .expect("the table names the quiet fork");
    assert!(quiet.ends_with("no standing projection at the close"));
    assert_eq!(
        golden
            .iter()
            .filter(|line| line.as_str()
                == "competitor quiet fork, no standing projection at the close")
            .count(),
        3
    );
}

#[test]
fn test_the_constructed_golden_carries_the_late_entry_shape() {
    let golden = golden_lines("constructed-meet-standings-golden.txt");
    let first_section_none = golden
        .iter()
        .position(|line| line == "competitor late riser, no standing projection at the close")
        .expect("the first section states the late riser in the none form");
    let first_figure = golden
        .iter()
        .position(|line| line.starts_with("competitor late riser, standing projection "))
        .expect("a later section states the late riser in figures");
    assert!(first_section_none < first_figure);
    assert_eq!(
        golden.last().map(String::as_str),
        Some("standings counts, days 3, competitors 3, standings held 8")
    );
}
